package com.mantou.salesdialer.contacts;
import android.app.Activity;import android.os.Bundle;import android.content.pm.ApplicationInfo;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import android.util.AtomicFile;import android.widget.TextView;
import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.nio.ByteBuffer;import java.util.*;import org.json.*;
import com.mantou.salesdialer.contacts.PhoneIntakeModel.DataClass;
/** Fixed private intake files only. Verifies every legacy field except the expected schema version. No phone. */
public final class PhoneIntakeUpgradeActivity extends Activity {
 private static final String[] TABLES={"phone_meta","phone_contacts","phone_batches","phone_rows","phone_events","phone_drafts","phone_draft_events","phone_plan","phone_plan_events","phone_attempts","phone_attempt_events","phone_cancellations"};
 private static final String[] ORDER={"singleton","id","id","batch,position","seq","target","seq","singleton","seq","id","seq","attempt"};
 private static void frame(MessageDigest d,byte[] value){d.update(ByteBuffer.allocate(4).putInt(value.length).array());d.update(value);}
 private String digest(String name,int version)throws Exception{int count=version==1?5:version==2?7:version==3?9:version==4?11:12;var hash=MessageDigest.getInstance("SHA-256");try(SQLiteDatabase db=SQLiteDatabase.openDatabase(getDatabasePath(name).getAbsolutePath(),null,SQLiteDatabase.OPEN_READONLY)){for(int i=0;i<count;i++){frame(hash,TABLES[i].getBytes(StandardCharsets.UTF_8));try(Cursor c=db.rawQuery("SELECT * FROM "+TABLES[i]+" ORDER BY "+ORDER[i],null)){while(c.moveToNext())for(int k=0;k<c.getColumnCount();k++){if(i==0&&c.getColumnName(k).equals("version"))continue;int type=c.getType(k);hash.update((byte)type);frame(hash,type==Cursor.FIELD_TYPE_NULL?new byte[0]:type==Cursor.FIELD_TYPE_BLOB?c.getBlob(k):c.getString(k).getBytes(StandardCharsets.UTF_8));}}}}StringBuilder result=new StringBuilder();for(byte b:hash.digest())result.append(String.format(Locale.ROOT,"%02x",b&255));return result.toString();}
 private JSONObject upgrade(DataClass mode)throws Exception{String name=mode==DataClass.LOCAL_PHONE_INTAKE?"local-phone-intake-v1.db":"phone-format-workspace-v1.db";if(!getDatabasePath(name).isFile())throw new IllegalStateException("EXISTING_PHONE_WORKSPACE_REQUIRED");int beforeVersion;try(SQLiteDatabase db=SQLiteDatabase.openDatabase(getDatabasePath(name).getAbsolutePath(),null,SQLiteDatabase.OPEN_READONLY)){beforeVersion=db.getVersion();}if(beforeVersion<1||beforeVersion>5)throw new IllegalStateException("UNSUPPORTED_PHONE_SCHEMA");String before=digest(name,beforeVersion);JSONObject r=new JSONObject().put("dataClass",mode.name()).put("fromVersion",beforeVersion);try(PhoneIntakeStore s=PhoneIntakeStore.open(this,mode)){JSONArray contacts=new JSONArray(),drafts=new JSONArray();for(var c:s.list())contacts.put(new JSONObject().put("id",c.id).put("maskedNumber",c.maskedNumber).put("qualification",c.qualification.name()).put("refused",c.refused).put("revision",c.revision));for(var d:s.drafts())drafts.put(new JSONObject().put("id",d.draft.id).put("targetId",d.draft.targetId).put("contactRevision",d.draft.contactRevision).put("status",d.status).put("dataClass",d.draft.dataClass.name()));var p=s.plan();r.put("contacts",contacts).put("drafts",drafts).put("attemptCount",s.pilotAttempts().size()).put("planVersion",p.plan.version).put("planPaused",p.plan.paused);}
  String after=digest(name,beforeVersion);if(!before.equals(after))throw new IllegalStateException("LEGACY_PHONE_BUSINESS_CHANGED");return r.put("toVersion",5).put("legacyDigestBefore",before).put("legacyDigestAfter",after).put("legacyBusinessUnchanged",true);
 }
 @Override public void onCreate(Bundle saved){super.onCreate(saved);TextView text=new TextView(this);text.setText("检查固定资料区升级；保留名单和历史，不拨号。");setContentView(text);if((getApplicationInfo().flags&ApplicationInfo.FLAG_DEBUGGABLE)==0){finish();return;}new Thread(()->{JSONObject report=new JSONObject();boolean ok=false;try{JSONArray areas=new JSONArray();areas.put(upgrade(DataClass.LOCAL_PHONE_INTAKE));areas.put(upgrade(DataClass.FORMAT_FIXTURE));report.put("areas",areas).put("decision","PASSED");ok=true;}catch(Exception e){try{String code=e.getMessage();report.put("decision","FAILED").put("errorCode",code!=null&&code.matches("[A-Z_0-9]+")?code:"UPGRADE_CHECK_FAILED");}catch(Exception ignored){}}try{report.put("source","FIXED_PHONE_WORKSPACE_UPGRADE").put("actualPhoneCalls",0).put("realCallsEnabled",false);AtomicFile f=new AtomicFile(new File(getFilesDir(),"phone-upgrade-check.json"));FileOutputStream out=f.startWrite();out.write(report.toString().getBytes(StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){ok=false;}boolean result=ok;runOnUiThread(()->text.setText(result?"资料升级完整性检查通过":"升级检查未通过，请保留数据。"));},"phone-upgrade-check").start();}
}
